mapper.select:
SELECT *
FROM payments
WHERE subscription_id = #{subscriptionId}
  AND billing_cycle_key = #{billingCycleKey}
ORDER BY attempt_no DESC
LIMIT 1

mapper.update:
UPDATE payments
SET status = 'UNKNOWN',
failure_code = #{failureCode},
failure_message = #{failureMessage}
WHERE id = #{id}
AND status = 'REQUESTED'
